 // Material for verification
 //==================================================================================================

 #[cfg(verus_keep_ghost)]
 verus! {

 impl View for PhysicalAddress
 {
     type V = int;

     closed spec fn view(&self) -> int
     {
         self.0@
     }
 }

 } // end verus!

